package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.Requests.*;import com.example.riskplatform.entity.RiskEvent;import com.example.riskplatform.service.RiskEventService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/risks") @RequiredArgsConstructor public class RiskEventController{private final RiskEventService s;@GetMapping @PreAuthorize("hasAuthority('risk:read')")public ApiResponse<List<RiskEvent>>list(@RequestParam(required=false)Long companyId,@RequestParam(required=false)String status,@RequestParam(required=false)String level){return ApiResponse.ok(s.list(companyId,status,level));}@PostMapping("/{id}/assign") @PreAuthorize("hasAuthority('risk:assign')")public ApiResponse<RiskEvent>assign(@PathVariable Long id,@Valid @RequestBody AssignRequest r){return ApiResponse.ok(s.assign(id,r.getAssigneeUserId()));}@PostMapping("/{id}/handle") @PreAuthorize("hasAuthority('risk:handle')")public ApiResponse<RiskEvent>handle(@PathVariable Long id,@Valid @RequestBody HandleRequest r){return ApiResponse.ok(s.handle(id,r.getHandleResult()));}@PostMapping("/{id}/review") @PreAuthorize("hasAuthority('risk:review')")public ApiResponse<RiskEvent>review(@PathVariable Long id,@Valid @RequestBody ReviewRequest r){return ApiResponse.ok(s.review(id,r.getReviewComment(),Boolean.TRUE.equals(r.getApproved())));}@PostMapping("/{id}/close") @PreAuthorize("hasAuthority('risk:close')")public ApiResponse<RiskEvent>close(@PathVariable Long id){return ApiResponse.ok(s.close(id));}}